function syncSharedLink(){const preview=!!(data.previewAccountId||data.previewPageId);$('#common-settings-toolbar').hidden=preview;$('#common-settings-link').hidden=sharedPage;$('#common-settings-link').href=sharedSettingsUrl();$('#desk-customer-context').hidden=!sharedPage||preview||['customers','customer-data'].includes(mode);const customer=data.customers.find(c=>c.id===commonCustomerId());const registering=!$('#directory-editor').hidden;$('#desk-customer-name').textContent=registering?'会社情報を入力中':customer?.name||'';$('#desk-customer-pick').disabled=registering;document.querySelectorAll('[data-common-destination]').forEach(b=>b.disabled=!customer);renderWebPublication()}
function publicationProfile(){const id=Number($('#org-root-customer').value),node=$('#web-publication-scope').value;return node?data.scopeProfiles?.find(p=>p.customer_id===id&&p.node_id===node):data.profiles.find(p=>p.customer_id===id)}
function renderWebPublication(){const id=Number($('#org-root-customer').value),panel=$('#web-publication-panel');if(!panel)return;panel.hidden=mode!=='web-settings'||!id;const select=$('#web-publication-scope'),old=select.value;select.innerHTML=(!data.manageCommonCustomerIds||data.manageCommonCustomerIds.includes(id)?'<option value="">会社全体の共通設定</option>':'')+(data.organizations?.nodes||[]).filter(n=>n.customer_id===id&&n.kind!=='company'&&(!data.allowedNodeIds||data.allowedNodeIds.includes(n.id))).map(n=>`<option value="${esc(n.id)}">${esc(n.name)}</option>`).join('');if([...select.options].some(o=>o.value===old))select.value=old;const p=publicationProfile();$('#web-publication-status').textContent=publicationText(p);for(const key of ['web-publish-common','web-pause-common'])$('#'+key).disabled=!p||busy}
async function publishCommon(action){const p=publicationProfile(),customer=Number($('#org-root-customer').value);if(!p||busy)return;if(window.WebRequestOrganization?.hasChanges())return notify('先にWEB依頼の設定を保存してください。');if(action==='pause'&&!confirm('選択した対象の受付を停止しますか？'))return;busy=true;renderWebPublication();try{await api({action,customer_id:customer,node_id:p.node_id||null,version:p.version,config:cleanConfig(p.draft),inheritance_mode:p.draft_mode||'inherit',parent_config:p.node_id?cleanConfig(p.parent_config):null});await loadSettings();notify(action==='pause'?'受付を停止しました。':'保存済みの契約・制服を依頼画面へ反映しました。')}catch(e){notify(e.message)}finally{busy=false;renderWebPublication()}}
$('#web-publication-scope').onchange=()=>{const p=publicationProfile();$('#web-publication-status').textContent=publicationText(p)};$('#web-publish-common').onclick=()=>publishCommon('publish');$('#web-pause-common').onclick=()=>publishCommon('pause');
function goToCustomerService(destination){const customer=commonCustomerId();if(!customer)return notify('先に顧客を選択してください。');if(window.WebRequestOrganization&&!window.WebRequestOrganization.canLeave())return;if(!leave())return;const url=new URL(destination==='rental'?'/rental':'/request-web',location.origin);url.searchParams.set('customer_id',customer);url.searchParams.set(destination==='rental'?'tab':'page',destination==='rental'?'home':'web-settings');location.href=url.pathname+url.search}
$('#desk-customer-pick').onclick=()=>openCustomerList({selectedId:commonCustomerId,select:id=>{if(window.WebRequestOrganization&&!window.WebRequestOrganization.canLeave())return;chooseCustomer(id);if(mode==='organization'){$('#org-root-customer').value=String(id);$('#org-root-customer').onchange()}syncSharedLink()}});
