function renderNewContractProducts(){if(!$('#new-contract-product-options'))return;document.querySelectorAll('#new-contract-product-options input').forEach(x=>x.checked?pickedNew.add(x.value):pickedNew.delete(x.value));const term=$('#new-contract-search').value.normalize('NFKC').toLowerCase();const rows=data.handles.filter(h=>h.customer_id===cid()).flatMap(h=>{const l=stockLabel(h);if(!l||!`${l.p.code} ${l.p.name} ${l.p.manufacturer||''} ${l.p.color} ${h.embroidery}`.normalize('NFKC').toLowerCase().includes(term)&&!pickedNew.has(String(h.id)))return [];return [`<label class="contract-product-option"><input type="checkbox" value="${h.id}" ${pickedNew.has(String(h.id))?'checked':''}><span><strong>${esc(l.text)}</strong><small>${esc(l.sub)}</small></span></label>`]});$('#new-contract-product-options').innerHTML=rows.join('')||'<p>該当する商品がありません。在庫管理でこの顧客の取扱商品を登録してください。</p>';renderNewContractPicked()}
function renderNewContractPicked(){document.querySelectorAll('#new-contract-product-options input').forEach(x=>x.checked?pickedNew.add(x.value):pickedNew.delete(x.value));const items=[...pickedNew].map(id=>data.handles.find(h=>String(h.id)===id)).filter(Boolean);$('#new-contract-picked').innerHTML=items.length?'選択中（'+items.length+'件）：'+items.map(h=>`<span class="picked-chip">${esc((stockLabel(h)?.text||'')+' ／ '+(h.embroidery||'加工なし'))}<button type="button" data-unpick="${h.id}" aria-label="選択を外す">×</button></span>`).join(''):'まだ選んでいません。契約を追加した後でも選べます。'}
