function pasteDeptContract(did){if(busy||deptLockedNotice()||!contractClipboard)return;if(contractClipboard.customer!==cid())return notify('同じ会社の部署に貼り付けてください。');const target=draft.departments.find(d=>d.id===did);if(!target)return;const k=clone(contractClipboard.contract);if(target.contracts.some(x=>x.name===k.name))return notify('この部署には同じ名前の契約があります。契約名を確認してください。');k.id=uid();delete k._source;k.uniforms.forEach(u=>{u.id=uid();delete u._source});target.contracts.push(k);pasteTarget=did;touch();renderRegisteredContracts();markPasteTarget(did);notify('「'+target.name+'」に契約と制服を貼り付けました。最後に設定を保存してください。')}
