async function assignDepartment(operation,all){if(busy)return;if(changed||pendingEditors.size)return notify('下の部署・契約の変更を先に保存してください。');const nodes=registrationNodes().filter(n=>all||bulkSelected.has(n.id)),lib=data.departmentLibraries?.find(l=>l.customer_id===cid());if(!nodes.length||!lib)return;if(!confirm('「'+lib.draft.departments.filter(d=>assignmentDepartments.has(d.id)).map(d=>d.name).join('、')+'」を'+nodes.map(n=>n.name).join('、')+' に'+(operation==='add'?'割り当てて保存':'割り当て解除して保存')+'しますか？'))return;busy=true;try{data=await api({action:'assign_department',customer_id:cid(),department_ids:[...assignmentDepartments],operation,library_version:lib.version,targets:nodes.map(n=>({node_id:n.id,version:data.departmentAssignments?.find(a=>a.node_id===n.id)?.version||0}))});draft=clone(profile().draft);renderDepartments();window.dispatchEvent(new Event('web-request-data'));notify('部署の割り当てを保存しました。')}catch(e){notify(e.message)}finally{busy=false;renderContractDiagram()}}
